interactive.starter:
var people = new List<Person>
{
    new("Ava", 30),
    new("Ben", 17),
    new("Cy", 45),
};

var adults = people
    .Where(p => p.Age >= 18)
    .OrderBy(p => p.Name)
    .Select(p => p.Name);

Console.WriteLine(string.Join(", ", adults));
Console.WriteLine($"Average age: {people.Average(p => p.Age):F1}");

record Person(string Name, int Age);

