interactive.starter:
var stock = new List<Item>
{
    new("Keyboard", 12, 60m),
    new("Monitor", 3, 220m),
    new("Mouse", 2, 25m),
};

Console.WriteLine("Low stock:");
foreach (var item in stock.Where(i => i.Qty < 5))
{
    Console.WriteLine($"  {item.Name} ({item.Qty} left)");
}

var value = stock.Sum(i => i.Qty * i.Price);
Console.WriteLine($"Total value: {value}");

record Item(string Name, int Qty, decimal Price);

